const lv_image_dsc_t *airspace_city_icon_for_key(const char *key)
{
    if (key == NULL) {
        return NULL;
    }
if (strcasecmp(key, "SJC") == 0) {
    return &airspace_menu_icon_sjc;
}
if (strcasecmp(key, "SFO") == 0) {
    return &airspace_menu_icon_sfo;
}
if (strcasecmp(key, "SAN") == 0) {
    return &airspace_menu_icon_san;
}
if (strcasecmp(key, "JFK") == 0) {
    return &airspace_menu_icon_jfk;
}
if (strcasecmp(key, "MOW") == 0) {
    return &airspace_menu_icon_mow;
}
if (strcasecmp(key, "LED") == 0) {
    return &airspace_menu_icon_led;
}
if (strcasecmp(key, "DUS") == 0) {
    return &airspace_menu_icon_dus;
}
if (strcasecmp(key, "ICN") == 0) {
    return &airspace_menu_icon_icn;
}
    return NULL;
}
